import{_ as r,a0 as p,w as u,s as d,ao as i,I as e,x as o,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"在 Mac OS X 系統中創建用於 Mac 的 Ubuntu USB 啓動盤 | LCTT x X-CMD","titleTemplate":false,"description":"在 Mac OS X 系統中創建用於 Mac 的 Ubuntu USB 啓動盤 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Mac OS X 系統中創建用於 Mac 的 Ubuntu USB 啓動盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Mac OS X 系統中創建用於 Mac 的 Ubuntu USB 啓動盤 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141205 How To Create A Bootable Ubuntu USB Drive For Mac In OS X","title":"在 Mac OS X 系統中創建用於 Mac 的 Ubuntu USB 啓動盤","tag":"201501","desc":""},"relativePath":"201501/20141205 How To Create A Bootable Ubuntu USB Drive For Mac In OS X.md","filePath":"[post].md"}'),l={name:"201501/20141205 How To Create A Bootable Ubuntu USB Drive For Mac In OS X.md"};function S(b,t,U,m,f,c){const s=p("Link");return u(),d("div",null,[t[25]||(t[25]=i('<h1 id="在-mac-os-x-系統中創建用於-mac-的-ubuntu-usb-啓動盤" tabindex="-1">在 Mac OS X 系統中創建用於 Mac 的 Ubuntu USB 啓動盤 <a class="header-anchor" href="#在-mac-os-x-系統中創建用於-mac-的-ubuntu-usb-啓動盤" aria-label="Permalink to “在 Mac OS X 系統中創建用於 Mac 的 Ubuntu USB 啓動盤”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Create_bootable_Ubuntu_USB_Mac_OS_X.jpg" alt=""></p><p>上個月，在戴爾的服務中心丟失我的筆記本後，我買了一台 Macbook Air 筆記本。買回來後我首先做的一些事就是給機器裝上雙系統，使 Ubuntu Linux 和 Mac OS X 都可用。隨後的文章我會介紹如何在 Macbook 上安裝 Linux ,剛開始我們需要學習 <strong>如何在 Mac OS X 系統中創建用於 Mac 的 Ubuntu USB 啓動盤</strong>。</p><p>在 Ubuntu 系統或 Windows 系統中創建可啓動的 USB 是非常容易的，但在 Mac OS X 系統中就沒這麼簡單了。這就是為什麼 Ubuntu 的官方指南上，在 Mac 中安裝 live Ubuntu 推薦使用光盤安裝而不是 USB 的原因。考慮到我的 Macbook Air 既沒有 CD 驅動也沒有 DVD 驅動，所以我更願意在 Mac OS X 下創建一個 live USB。</p><h3 id="在-mac-os-x-下創建可啓動-usb-驅動盤" tabindex="-1">在 Mac OS X 下創建可啓動 USB 驅動盤### <a class="header-anchor" href="#在-mac-os-x-下創建可啓動-usb-驅動盤" aria-label="Permalink to “在 Mac OS X 下創建可啓動 USB 驅動盤###”">​</a></h3><p>如前所述，在 Mac OS X 上創建對於像 Ubuntu 或任何其它可引導的操作系統這樣的可啓動 USB 盤是個比較麻煩的過程。但請別擔心，按照下面的步驟一步一步操作就行。讓我們就開始創建一個可啓動的 USB 盤的操作吧：</p><h4 id="步驟-1-格式化-usb-驅動盤" tabindex="-1">步驟 1: 格式化 USB 驅動盤 <a class="header-anchor" href="#步驟-1-格式化-usb-驅動盤" aria-label="Permalink to “步驟 1: 格式化 USB 驅動盤”">​</a></h4>',7)),e("p",null,[t[1]||(t[1]=o("蘋果是以它自定義的標準而聞名的，所以 Mac OS X 系統有自己的文件系統類型就毫不奇怪了，它的文件系統叫做 Mac OS 擴展或 ",-1)),a(s,{href:"http://en.wikipedia.org/wiki/HFS_Plus"},{default:n(()=>[...t[0]||(t[0]=[o("HFS 插件",-1)])]),_:1}),t[2]||(t[2]=o("。因此，您需要做的第一件事就是用 Mac OS 擴展文件系統來格式化您的 USB 驅動盤。",-1))]),t[26]||(t[26]=i('<p>要格式化 USB 盤，請先插入 USB 盤。從 Launchpad（在底部面板上的一個火箭形狀的圖標）上前往<strong>磁盤工具</strong>應用程序。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Disk_Utility_Mac.jpg" alt=""></p><ul><li>在磁盤工具中，從左手邊的面板上選擇你的 USB 盤來格式化。</li><li>點擊右邊面板的<strong>分區</strong>標籤。</li><li>從下拉菜單中，選擇 <strong>1 分區</strong>。</li><li>給這驅動盤起個您想要的名字。</li><li>接下來，切換分區格式為<strong>格式化成 Mac OS 擴展 (日誌型)</strong></li></ul><p>下面的截屏將會對您有所幫助。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Format_Usb_Mac_4.jpg" alt=""></p><p>在我們開始真正格式化 USB 盤之前這是唯一一件要做的操作。點擊在右邊面板的選項按紐，要確保分區的模式是 <strong>GUID 分區表</strong>形式的。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Format_Usb_Mac_2.jpg" alt=""></p><p>當所有都已經設置完了後，僅僅只需點擊<strong>應用</strong>按紐。它會彈出一個要格式化 USB 驅動盤的警告消息，當然是要點擊分區按紐來格式化 USB 驅動盤拉。</p><h4 id="步驟-2-下載-ubuntu" tabindex="-1">步驟 2: 下載 Ubuntu <a class="header-anchor" href="#步驟-2-下載-ubuntu" aria-label="Permalink to “步驟 2: 下載 Ubuntu”">​</a></h4>',9)),e("p",null,[t[4]||(t[4]=o("當然，您需要下載 Ubuntu 桌面版本的 ISO 鏡像文件。鏈接到",-1)),a(s,{href:"http://www.ubuntu.com/download/desktop"},{default:n(()=>[...t[3]||(t[3]=[o(" Ubuntu 官網去下載您喜歡的 Ubuntu 桌面版本系統",-1)])]),_:1}),t[5]||(t[5]=o("。因為您使用的是 Macbook Air，我建議您下載 64 位版本中的一款。Ubuntu 14.04 是最新的 LTS 版本，我建議您們使用它。",-1))]),t[27]||(t[27]=e("h4",{id:"步驟-3-把-iso-格式轉成-img-格式",tabindex:"-1"},[o("步驟 3: 把 ISO 格式轉成 IMG 格式 "),e("a",{class:"header-anchor",href:"#步驟-3-把-iso-格式轉成-img-格式","aria-label":"Permalink to “步驟 3: 把 ISO 格式轉成 IMG 格式”"},"​")],-1)),e("p",null,[t[7]||(t[7]=o("您下載的文件是 ISO 格式的，但我們需要它是 IMG 格式的，使用 ",-1)),a(s,{href:"https://developer.apple.com/library/mac/documentation/Darwin/Reference/ManPages/man1/hdiutil.1.html"},{default:n(()=>[...t[6]||(t[6]=[o("hdiutil",-1)])]),_:1}),t[8]||(t[8]=o(" 命令工具就可以很容易的轉換。打開終端，也可以從 Launchpad 或 Spotlight 中打開，然後使用如下的命令就可以把 ISO 格式的轉換成 IMG 格式的了:",-1))]),t[28]||(t[28]=i(`<pre><code>hdiutil convert -format UDRW -o ~/Path-to-IMG-file ~/Path-to-ISO-file
</code></pre><p>通常下載的文件會在 ~/Downloads 目錄下。所以在我的系統來，輸入的命令是:</p><pre><code>hdiutil convert -format UDRW -o ~/Downloads/ubuntu-14.10-desktop-amd64 ~/Downloads/ubuntu-14.10-desktop-amd64.iso
</code></pre><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/ISO_to_IMG_Convert_Mac_OS_X.jpeg" alt=""></p><p>您可能已經注意到我並沒有新轉換出的文件加上 IMG 後綴。這是沒問題的，因為後綴只是個標誌，重要的是文件類型並不是文件的擴展名。轉換出來的文件可能會被 Mac OS X 系統自動加上個 .dmg 後綴。別擔心，這是正常的。</p><h4 id="步驟-4-獲得-usb-盤的設備號" tabindex="-1">步驟 4: 獲得 USB 盤的設備號 <a class="header-anchor" href="#步驟-4-獲得-usb-盤的設備號" aria-label="Permalink to “步驟 4: 獲得 USB 盤的設備號”">​</a></h4><p>接下來的事情就是獲得 USB 盤的設備號。在終端中運行如下命令：</p><pre><code>diskutil list
</code></pre><p>它會列出系統中當前可用的所有‘磁盤’信息。從它的大小上您應該能識別出此 USB 盤。為了避免混淆，我建議您只插入一個 USB 盤。我的示例中，設置號是 2 （一個大小為 8G 的 USB）: /dev/disk2</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Create_bootable_USB_Mac_OSX.jpeg" alt=""></p><p>當得到設備號後，運行如下命令：</p><pre><code>diskutil unmountDisk /dev/diskN
</code></pre><p>這兒的 N 就是前面您得到的 USB 的設備號。所以，我的示例中，上面的命令就變成：</p><pre><code>diskutil unmountDisk /dev/disk2
</code></pre><p>執行結果應該是：<strong>成功的卸載 disk2 上的所有卷</strong>。</p><h4 id="步驟-5-在-mac-os-x-中創建可啓動的-usb-驅動盤" tabindex="-1">步驟 5: 在 Mac OS X 中創建可啓動的 USB 驅動盤#### <a class="header-anchor" href="#步驟-5-在-mac-os-x-中創建可啓動的-usb-驅動盤" aria-label="Permalink to “步驟 5: 在 Mac OS X 中創建可啓動的 USB 驅動盤####”">​</a></h4>`,16)),e("p",null,[t[10]||(t[10]=o("終於我們只有創建可啓動的 USB 盤這最後一步了。我們會使用 ",-1)),a(s,{href:"http://en.wikipedia.org/wiki/Dd_%28Unix%29"},{default:n(()=>[...t[9]||(t[9]=[o("dd 命令",-1)])]),_:1}),t[11]||(t[11]=o("，它非常的強大，必須得小心使用。因此，一定要記得您 USB 驅動盤的正確設備號，要不然會使 Mac OS X 系統崩潰。在終端中使用如下命令:",-1))]),t[29]||(t[29]=i(`<pre><code>sudo dd if=/Path-to-IMG-DMG-file of=/dev/rdiskN bs=1m
</code></pre><p>這兒我們使用 dd (拷貝和轉換) 來把 IMG 輸入文件 (if) 拷貝和轉換到 磁盤 N 中。我希望您還記得在步驟 3 中已經生成的 IMG 文件的存放位置。對我的機器來説，命令如下所示：</p><pre><code>sudo dd if=~/Downloads/ubuntu-14.10-desktop-amd64.dmg of=/dev/rdisk2 bs=1m
</code></pre><p>我們用超級用户權限（sudo）來運行上面的命令，還需要您輸入密碼。跟 Linux 中類似，您從鍵盤中輸入密碼時，將看不到任何星號或顯示的提示，不用擔心，這是 Unix 終端的習慣。</p><p>甚至在您輸入完密碼後，<strong>您都不會看到立即的輸出，這是正常的</strong>。需要一小會兒時間才會處理完成。</p><h4 id="步驟-6-完成可啓動-usb-驅動盤的整個處理過程" tabindex="-1">步驟 6: 完成可啓動 USB 驅動盤的整個處理過程 <a class="header-anchor" href="#步驟-6-完成可啓動-usb-驅動盤的整個處理過程" aria-label="Permalink to “步驟 6: 完成可啓動 USB 驅動盤的整個處理過程”">​</a></h4><p>一旦 DD 命令處理完成，會彈出一個對話框：<strong>您插入的磁盤在這機器上不可讀</strong>。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Bootable_USB_3.png" alt=""></p><p>別驚慌，一切正常。只是<strong>現在不要點擊初始化、忽略或彈出按紐</strong>。回到終端，您會看到最新處理完成的一些信息。我的機器中顯示如下：</p><blockquote><p>1109+1 records in</p><p>1109+1 records out</p><p>1162936320 bytes transferred in 77.611025 secs (14984164 bytes/sec)</p></blockquote><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Create_bootable_USB_Mac_OSX_1.jpeg" alt=""></p><p>現在，在終端中使用如下命令來彈出我們的 USB 驅動盤：</p><pre><code>diskutil eject /dev/diskN
</code></pre><p>N 當然指的是我們前面使用過的設備號，在我的示例中是 2 ：</p><pre><code>diskutil eject /dev/disk2
</code></pre><p>一旦彈出，點擊前面出現那對話框上的<strong>忽略</strong>按紐。現在您的可啓動 USB 磁盤已經創建好了，把它拔下來吧。</p><h4 id="步驟-7-檢查您新創建的可啓動-usb-盤" tabindex="-1">步驟 7: 檢查您新創建的可啓動 USB 盤 <a class="header-anchor" href="#步驟-7-檢查您新創建的可啓動-usb-盤" aria-label="Permalink to “步驟 7: 檢查您新創建的可啓動 USB 盤”">​</a></h4><p>一旦您在 Mac OS X 中完成了創建一個 live USB 這麼重大的任務，是時候測試您的新成果了。</p><ul><li>插入可啓動 USB 盤，重啓系統。</li><li>在蘋果啓動的時候，一直按着 option （或 alt）鍵。</li><li>這會引導您進入啓動時需要訪問的可使用磁盤界面。我假設您知道接下來的操作步驟。</li></ul><p>對我機器來説它顯示了兩個 EFI 啓動盤：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Ubuntu_boot_USB_Mac_OSX_1.jpeg" alt=""></p><p>我選擇第一個，然後它就會直接進入 Grub 界面：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/11/Ubuntu_boot_USB_Mac_OSX.jpeg" alt=""></p><p>我希望這篇教程對您想要在 Mac OS X 下創建可啓動的 Ubuntu 系統 USB 驅動盤有所幫助。在接下來的一篇文章中您會學到怎麼樣安裝 OS X 和 Ubuntu 雙系統。請繼續關注。</p><hr>`,25)),e("p",null,[t[13]||(t[13]=o("via: ",-1)),a(s,{href:"http://itsfoss.com/create-bootable-ubuntu-usb-drive-mac-os/"},{default:n(()=>[...t[12]||(t[12]=[o("http://itsfoss.com/create-bootable-ubuntu-usb-drive-mac-os/",-1)])]),_:1})]),e("p",null,[t[17]||(t[17]=o("作者：",-1)),a(s,{href:"http://itsfoss.com/author/Abhishek/"},{default:n(()=>[...t[14]||(t[14]=[o("Abhishek",-1)])]),_:1}),t[18]||(t[18]=o(" 譯者：",-1)),a(s,{href:"https://github.com/runningwater"},{default:n(()=>[...t[15]||(t[15]=[o("runningwater",-1)])]),_:1}),t[19]||(t[19]=o(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[16]||(t[16]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[22]||(t[22]=o("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[20]||(t[20]=[o("LCTT",-1)])]),_:1}),t[23]||(t[23]=o(" 原創翻譯，",-1)),a(s,{href:"http://linux.cn/"},{default:n(()=>[...t[21]||(t[21]=[o("Linux中國",-1)])]),_:1}),t[24]||(t[24]=o(" 榮譽推出",-1))])])}const B=r(l,[["render",S]]);export{g as __pageData,B as default};
